class Base:
 def value(self): return 3
class Child(Base):
 value=lambda self:super().value()+1
print(Child().value())

f=lambda value=3:(yield value)
g=f()
print(next(g))
try:g.send(7)
except StopIteration as done:print(done.value)

def outer():
 value=7
 def middle():
  return lambda:value
 return middle
print(outer()()())
